using SaveToolkit.Core.Storage;
using SaveToolkit.Testing;

namespace SaveToolkit.Plugins.EldenRing.Tests;

// Core sessions require a DiskSaveFile. Import generated bytes rather than borrowing
// unrelated private sample metadata, and own the imported blobs for the whole session.
internal sealed class SyntheticDiskSave : IDisposable
{
    private const string RelativePath = "PPSA03169/sdimg_sce_sdmemory/memory.dat";

    public SyntheticDiskSave(byte[] bytes)
    {
        try
        {
            var set = SaveSetImporter.Import([new(RelativePath, () => new MemoryStream(bytes, writable: false))], Root);
            File = Assert.Single(set.AllDiskFiles);
        }
        catch
        {
            Dispose();
            throw;
        }
    }

    public string Root { get; } = Path.Combine(TestScratch.ProcessFolder, $"eldenring-{Guid.NewGuid():N}");
    public DiskSaveFile File { get; }

    public void Dispose()
    {
        if (Directory.Exists(Root)) Directory.Delete(Root, recursive: true);
    }
}
